import React from "react";

import {
    FaSearch,
    FaFilter,
    FaTh,
    FaBars,
} from "react-icons/fa";

import FilterModal from "./FilterModalComponent";
import RequestRecords from "./RequestRecordsComponent";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL =
    "https://iranaserviceapp.ir/test/api";

class RequestsPage extends React.Component {
    constructor(props) {
        super(props);

        this.state = {
            activeTab: "waiting",
            search: "",
            viewMode: "card",

            isFilterOpen: false,

            province: "",
            startDate: "",
            endDate: "",

            records: [],

            loading: true,
            authenticated: false,
        };
    }

    componentDidMount() {
        const isAuthenticated = AuthCheck();

        if (!isAuthenticated) {
            return;
        }

        this.setState(
            {
                authenticated: true,
            },
            () => {
                this.getRequests();
            }
        );
    }

    // =========================================================
    // گرفتن مقدار رشته‌ای از آبجکت
    // =========================================================

    getPersonName = (person) => {
        if (!person) {
            return "";
        }

        // اگر مستقیماً string باشد
        if (typeof person === "string") {
            return person.trim();
        }

        // اگر number باشد
        if (
            typeof person === "number"
        ) {
            return String(person);
        }

        if (
            typeof person !== "object"
        ) {
            return "";
        }

        // اگر name کامل وجود داشته باشد
        if (
            typeof person.name ===
                "string" &&
            person.name.trim()
        ) {
            const family =
                person.family ||
                person.last_name ||
                person.lastname ||
                "";

            return `${person.name.trim()} ${String(
                family
            ).trim()}`.trim();
        }

        // حالت first_name / last_name
        const firstName =
            person.first_name ||
            person.firstname ||
            "";

        const lastName =
            person.last_name ||
            person.lastname ||
            person.family ||
            "";

        if (
            firstName ||
            lastName
        ) {
            return `${firstName} ${lastName}`.trim();
        }

        // بعضی APIها ممکن است full_name داشته باشند
        if (
            person.full_name
        ) {
            return String(
                person.full_name
            ).trim();
        }

        if (
            person.fullName
        ) {
            return String(
                person.fullName
            ).trim();
        }

        return "";
    };

    // =========================================================
    // پیدا کردن تعمیرکار
    // =========================================================

    getTechnicianName = (
        request
    ) => {
        if (!request) {
            return "---";
        }

        // -----------------------------------------------------
        // اول فیلدهایی که مستقیماً اسم تعمیرکار هستند
        // -----------------------------------------------------

        const directFields = [
            "technician_name",
            "repairman_name",
            "repairmanName",
            "technicianName",
            "repairer_name",
            "repairerName",
            "technician_full_name",
            "repairman_full_name",
            "technician_fullname",
            "repairman_fullname",
        ];

        for (
            let i = 0;
            i < directFields.length;
            i++
        ) {
            const field =
                directFields[i];

            const value =
                request[field];

            if (
                value !== null &&
                value !== undefined &&
                String(value).trim()
            ) {
                return String(
                    value
                ).trim();
            }
        }

        // -----------------------------------------------------
        // فیلدهایی که ممکن است object باشند
        // -----------------------------------------------------

        const objectFields = [
            "repairman",
            "repairman_model",
            "technician",
            "technician_model",
            "repairer",
            "repairer_model",
            "worker",
            "worker_model",
        ];

        for (
            let i = 0;
            i < objectFields.length;
            i++
        ) {
            const field =
                objectFields[i];

            const value =
                request[field];

            const name =
                this.getPersonName(
                    value
                );

            if (name) {
                return name;
            }
        }

        // -----------------------------------------------------
        // بعضی APIها تعمیرکار را داخل user برمی‌گردانند
        // -----------------------------------------------------

        const possibleUsers = [
            request.user,
            request.user_model,
            request.customer,
            request.customer_model,
        ];

        for (
            let i = 0;
            i < possibleUsers.length;
            i++
        ) {
            const user =
                possibleUsers[i];

            if (!user) {
                continue;
            }

            // اگر user خودش تعمیرکار مشخص شده
            if (
                user.role ===
                    "repairman" ||
                user.role ===
                    "technician" ||
                user.type ===
                    "repairman" ||
                user.type ===
                    "technician"
            ) {
                const name =
                    this.getPersonName(
                        user
                    );

                if (name) {
                    return name;
                }
            }
        }

        return "---";
    };

    // =========================================================
    // تبدیل یک request به record
    // =========================================================

    normalizeRequest = (
        request
    ) => {
        if (!request) {
            return null;
        }

        const customer =
            request.user ||
            request.customer ||
            request.user_model ||
            request.customer_model ||
            {};

        const customerName =
            request.customerName ||
            request.customer_name ||
            request.full_name ||
            request.fullName ||
            request.name ||
            this.getPersonName(
                customer
            ) ||
            "---";

        const technician =
            this.getTechnicianName(
                request
            );

        return {
            id:
                request.id,

            customerName:
                customerName,

            deviceType:
                request.deviceType ||
                request.device_type ||
                request.type ||
                request.device ||
                request.device_name ||
                request.device_type_name ||
                "---",

            deviceBrand:
                request.deviceBrand ||
                request.device_brand ||
                request.brand ||
                request.brand_name ||
                request.device_brand_name ||
                "---",

            technician:
                technician,

            problem:
                request.problem ||
                request.device_problem ||
                request.description ||
                request.issue ||
                "---",

            date:
                request.time ||
                request.date ||
                request.created_at ||
                "---",

            status:
                request.status_name ||
                request.status_text ||
                request.state_name ||
                request.status ||
                "waiting",

            province:
                request.state ??
                request.province ??
                "",

            city:
                request.city ??
                "",

            original:
                request,
        };
    };

    // =========================================================
    // دریافت درخواست‌ها
    // =========================================================

    getRequests = () => {
        const token =
            localStorage.getItem(
                "token"
            );

        this.setState({
            loading: true,
        });

        fetch(
            `${API_URL}/list`,
            {
                method: "GET",

                headers: {
                    Accept:
                        "application/json",

                    Authorization:
                        `Bearer ${token}`,
                },
            }
        )
            .then((response) => {
                if (!response.ok) {
                    throw new Error(
                        "خطا در دریافت درخواست‌ها"
                    );
                }

                return response.json();
            })
            .then((data) => {
                console.log(
                    "LIST JSON:",
                    data
                );

                let requests = [];

                // -------------------------------------------------
                // پیدا کردن آرایه API
                // -------------------------------------------------

                if (
                    Array.isArray(data)
                ) {
                    requests = data;
                } else if (
                    Array.isArray(
                        data?.requests
                    )
                ) {
                    requests =
                        data.requests;
                } else if (
                    Array.isArray(
                        data?.data
                    )
                ) {
                    requests =
                        data.data;
                } else if (
                    Array.isArray(
                        data?.list
                    )
                ) {
                    requests =
                        data.list;
                }

                // -------------------------------------------------
                // normalize
                // -------------------------------------------------

                const records =
                    requests
                        .map(
                            (
                                request
                            ) =>
                                this.normalizeRequest(
                                    request
                                )
                        )
                        .filter(
                            Boolean
                        );

                console.log(
                    "NORMALIZED RECORDS:",
                    records
                );

                // -------------------------------------------------
                // خیلی مهم:
                // ابتدا records را ست می‌کنیم
                // بعد loading را false می‌کنیم
                // -------------------------------------------------

                this.setState(
                    {
                        records:
                            Array.isArray(
                                records
                            )
                                ? records
                                : [],

                        loading: false,
                    }
                );
            })
            .catch((error) => {
                console.error(
                    "GET REQUESTS ERROR:",
                    error
                );

                this.setState({
                    records: [],
                    loading: false,
                });
            });
    };

    // =========================================================
    // Search
    // =========================================================

    handleSearchChange = (
        e
    ) => {
        this.setState({
            search:
                e.target.value,
        });
    };

    // =========================================================
    // Tabs
    // =========================================================

    handleTabChange = (
        tab
    ) => {
        this.setState({
            activeTab: tab,
        });
    };

    // =========================================================
    // View Mode
    // =========================================================

    handleViewModeChange = (
        mode
    ) => {
        this.setState({
            viewMode: mode,
        });
    };

    // =========================================================
    // Filter
    // =========================================================

    handleOpenFilter = () => {
        this.setState({
            isFilterOpen: true,
        });
    };

    handleCloseFilter = () => {
        this.setState({
            isFilterOpen: false,
        });
    };

    handleProvinceChange = (
        e
    ) => {
        this.setState({
            province:
                e.target.value,
        });
    };

    // =========================================================
    // Start Date
    // =========================================================

    handleStartDateChange = (
        date
    ) => {
        if (!date) {
            this.setState({
                startDate: "",
            });

            return;
        }

        this.setState({
            startDate: date,
        });
    };

    // =========================================================
    // End Date
    // =========================================================

    handleEndDateChange = (
        date
    ) => {
        if (!date) {
            this.setState({
                endDate: "",
            });

            return;
        }

        this.setState({
            endDate: date,
        });
    };

    // =========================================================
    // Gregorian Date
    // =========================================================

    getGregorianDate = (
        date
    ) => {
        if (!date) {
            return "";
        }

        try {
            if (
                typeof date.toDate ===
                "function"
            ) {
                const javascriptDate =
                    date.toDate();

                return `${javascriptDate.getFullYear()}-${String(
                    javascriptDate.getMonth() +
                        1
                ).padStart(
                    2,
                    "0"
                )}-${String(
                    javascriptDate.getDate()
                ).padStart(
                    2,
                    "0"
                )}`;
            }

            const value =
                String(
                    date
                ).trim();

            if (
                /^\d{4}-\d{2}-\d{2}$/.test(
                    value
                )
            ) {
                return value;
            }

            return "";
        } catch (
            error
        ) {
            console.error(
                "GET GREGORIAN DATE ERROR:",
                error
            );

            return "";
        }
    };

    // =========================================================
    // Apply Filter
    // =========================================================

    handleApplyFilter =
        () => {
            const {
                province,
                startDate,
                endDate,
            } = this.state;

            const start =
                this.getGregorianDate(
                    startDate
                );

            const end =
                this.getGregorianDate(
                    endDate
                );

            console.log(
                "APPLIED FILTER:",
                {
                    province,
                    startDate:
                        start,
                    endDate:
                        end,
                }
            );

            this.setState({
                isFilterOpen:
                    false,
            });
        };

    // =========================================================
    // Normalize Date
    // =========================================================

    normalizeDate = (
        date
    ) => {
        if (!date) {
            return "";
        }

        let value =
            String(
                date
            ).trim();

        if (!value) {
            return "";
        }

        if (
            value.includes(
                "T"
            )
        ) {
            value =
                value.split(
                    "T"
                )[0];
        }

        value =
            value.replace(
                /\//g,
                "-"
            );

        if (
            /^\d{4}-\d{2}-\d{2}$/.test(
                value
            )
        ) {
            return value;
        }

        return "";
    };

    // =========================================================
    // Filter Records
    // =========================================================

    getFilteredRequests =
        () => {
            const {
                records,
                activeTab,
                search,
                province,
                startDate,
                endDate,
            } = this.state;

            const safeRecords =
                Array.isArray(
                    records
                )
                    ? records
                    : [];

            const searchText =
                search
                    .trim()
                    .toLowerCase();

            const selectedStartDate =
                this.getGregorianDate(
                    startDate
                );

            const selectedEndDate =
                this.getGregorianDate(
                    endDate
                );

            return safeRecords.filter(
                (record) => {
                    let matchesTab =
                        true;

                    const status =
                        String(
                            record.status ||
                                ""
                        ).toLowerCase();

                    if (
                        activeTab ===
                        "waiting"
                    ) {
                        matchesTab =
                            status ===
                                "waiting" ||
                            status ===
                                "0" ||
                            status ===
                                "pending" ||
                            status ===
                                "pending_confirmation";
                    }

                    if (
                        activeTab ===
                        "confirmed"
                    ) {
                        matchesTab =
                            status ===
                                "confirmed" ||
                            status ===
                                "1";
                    }

                    if (
                        !matchesTab
                    ) {
                        return false;
                    }

                    // Search
                    if (
                        searchText
                    ) {
                        const searchableText =
                            [
                                record.customerName,
                                record.deviceType,
                                record.deviceBrand,
                                record.technician,
                                record.problem,
                                record.province,
                                record.city,
                            ]
                                .map(
                                    (
                                        item
                                    ) =>
                                        String(
                                            item ||
                                                ""
                                        ).toLowerCase()
                                )
                                .join(
                                    " "
                                );

                        if (
                            !searchableText.includes(
                                searchText
                            )
                        ) {
                            return false;
                        }
                    }

                    // Province
                    if (
                        province
                    ) {
                        if (
                            String(
                                record.province
                            ) !==
                            String(
                                province
                            )
                        ) {
                            return false;
                        }
                    }

                    // Date
                    const requestDate =
                        this.normalizeDate(
                            record.date
                        );

                    if (
                        selectedStartDate
                    ) {
                        if (
                            !requestDate ||
                            requestDate <
                                selectedStartDate
                        ) {
                            return false;
                        }
                    }

                    if (
                        selectedEndDate
                    ) {
                        if (
                            !requestDate ||
                            requestDate >
                                selectedEndDate
                        ) {
                            return false;
                        }
                    }

                    return true;
                }
            );
        };

    // =========================================================
    // Render
    // =========================================================

    render() {
        const {
            authenticated,
            loading,
            activeTab,
            search,
            viewMode,
            isFilterOpen,
            province,
            startDate,
            endDate,
        } = this.state;

        if (!authenticated) {
            return <Loader />;
        }

        const filteredResult =
            this.getFilteredRequests();

        const filteredRequests =
            Array.isArray(
                filteredResult
            )
                ? filteredResult
                : [];

        return (
            <div className="container">
                <div
                    className="sticky-top bg-light"
                    style={{
                        zIndex: 1020,
                        padding:
                            "12px",
                    }}
                >
                    {/* Search */}

                    <div className="position-relative mb-3">
                        <FaSearch
                            className="position-absolute text-secondary"
                            style={{
                                left:
                                    "16px",
                                top:
                                    "50%",
                                transform:
                                    "translateY(-50%)",
                                zIndex: 2,
                            }}
                        />

                        <input
                            type="text"
                            value={
                                search
                            }
                            onChange={
                                this
                                    .handleSearchChange
                            }
                            placeholder="جستجو..."
                            className="form-control border rounded-pill shadow-none"
                            style={{
                                height:
                                    "58px",
                                paddingRight:
                                    "20px",
                                paddingLeft:
                                    "48px",
                                fontSize:
                                    "15px",
                            }}
                        />
                    </div>

                    {/* Tabs */}

                    <div
                        className="d-flex p-1 mb-3 rounded-pill"
                        style={{
                            background:
                                "#f5f2ff",
                            border:
                                "1px solid #eee9ff",
                        }}
                    >
                        <button
                            type="button"
                            onClick={() =>
                                this.handleTabChange(
                                    "waiting"
                                )
                            }
                            className="btn flex-grow-1 rounded-pill"
                            style={{
                                height:
                                    "52px",
                                background:
                                    activeTab ===
                                    "waiting"
                                        ? "#fff"
                                        : "transparent",
                                color:
                                    activeTab ===
                                    "waiting"
                                        ? "#5540a8"
                                        : "#aaa",
                                border:
                                    activeTab ===
                                    "waiting"
                                        ? "1px solid #7158c9"
                                        : "1px solid transparent",
                            }}
                        >
                            منتظر تایید تعمیرکار
                        </button>

                        <button
                            type="button"
                            onClick={() =>
                                this.handleTabChange(
                                    "confirmed"
                                )
                            }
                            className="btn flex-grow-1 rounded-pill"
                            style={{
                                height:
                                    "52px",
                                background:
                                    activeTab ===
                                    "confirmed"
                                        ? "#fff"
                                        : "transparent",
                                color:
                                    activeTab ===
                                    "confirmed"
                                        ? "#5540a8"
                                        : "#aaa",
                                border:
                                    activeTab ===
                                    "confirmed"
                                        ? "1px solid #7158c9"
                                        : "1px solid transparent",
                            }}
                        >
                            تایید شده
                        </button>
                    </div>

                    {/* Toolbar */}

                    <div className="d-flex align-items-center justify-content-between mb-2">
                        <button
                            type="button"
                            onClick={
                                this
                                    .handleOpenFilter
                            }
                            className="btn bg-white border rounded-4 d-flex align-items-center gap-3 px-4"
                            style={{
                                height:
                                    "58px",
                                color:
                                    "#777",
                            }}
                        >
                            <span>
                                فیلتر
                            </span>

                            <FaFilter
                                size={
                                    20
                                }
                            />
                        </button>

                        <div className="d-flex gap-2">
                            <button
                                type="button"
                                onClick={() =>
                                    this.handleViewModeChange(
                                        "list"
                                    )
                                }
                                className="btn bg-white border rounded-4 d-flex align-items-center justify-content-center"
                                style={{
                                    width:
                                        "58px",
                                    height:
                                        "58px",
                                    color:
                                        viewMode ===
                                        "list"
                                            ? "#4d3ba3"
                                            : "#888",
                                }}
                            >
                                <FaBars
                                    size={
                                        23
                                    }
                                />
                            </button>

                            <button
                                type="button"
                                onClick={() =>
                                    this.handleViewModeChange(
                                        "card"
                                    )
                                }
                                className="btn bg-white border rounded-4 d-flex align-items-center justify-content-center"
                                style={{
                                    width:
                                        "58px",
                                    height:
                                        "58px",
                                    color:
                                        viewMode ===
                                        "card"
                                            ? "#4d3ba3"
                                            : "#888",
                                }}
                            >
                                <FaTh
                                    size={
                                        23
                                    }
                                />
                            </button>
                        </div>
                    </div>
                </div>

                {/* Records */}

                {loading ? (
                    <div className="py-5">
                        <Loader />
                    </div>
                ) : (
                    <RequestRecords
                        records={
                            filteredRequests
                        }
                        viewMode={
                            viewMode ||
                            "card"
                        }
                    />
                )}

                {/* Filter */}

                <FilterModal
                    isOpen={
                        isFilterOpen
                    }
                    onClose={
                        this
                            .handleCloseFilter
                    }
                    onApply={
                        this
                            .handleApplyFilter
                    }
                    province={
                        province
                    }
                    startDate={
                        startDate
                    }
                    endDate={
                        endDate
                    }
                    onProvinceChange={
                        this
                            .handleProvinceChange
                    }
                    onStartDateChange={
                        this
                            .handleStartDateChange
                    }
                    onEndDateChange={
                        this
                            .handleEndDateChange
                    }
                />
            </div>
        );
    }
}

export default RequestsPage;
